#include "code_scan.h"
#include "checks_mem.h"
static int has_func_call(ASTNode*n,const char*name){if(!n)return 0;if(n->type==AST_CALL&&strcmp(n->name,name)==0)return 1;for(int i=0;i<ast_nchildren(n);i++){if(has_func_call(ast_child(n,i),name))return 1;}return 0;}
static int count_alloc_calls(ASTNode*n){if(!n)return 0;int c=0;if(n->type==AST_CALL){if(strcmp(n->name,"malloc")==0||strcmp(n->name,"calloc")==0||strcmp(n->name,"realloc")==0)c++;}for(int i=0;i<ast_nchildren(n);i++)c+=count_alloc_calls(ast_child(n,i));return c;}
static int count_free_calls(ASTNode*n,int*has_free){if(!n)return 0;int c=0;if(n->type==AST_CALL){if(strcmp(n->name,"free")==0){c++;if(has_free)*has_free=1;}}for(int i=0;i<ast_nchildren(n);i++)c+=count_free_calls(ast_child(n,i),has_free);return c;}
int check_null_deref(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-1;i++){Token*t=&f->tokens[i];if(t->type==TK_ID&&(strcmp(t->text,"NULL")==0||strcmp(t->text,"nullptr")==0)){for(int j=i+1;j<f->ntokens-2&&j<i+10;j++){if(f->tokens[j].type==TK_ARROW||f->tokens[j].type==TK_DOT){cnt++;if(cnt==1&&out){out->loc.line=t->line;out->loc.col=t->col;out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2001;snprintf(out->msg,sizeof(out->msg),"Potential NULL pointer dereference detected");snprintf(out->suggestion,sizeof(out->suggestion),"Check pointer for NULL before dereferencing");}}}}if(t->type==TK_ID&&strcmp(t->text,"free")==0){for(int j=i+1;j<f->ntokens-1;j++){if(f->tokens[j].type==TK_ID&&f->tokens[j+1].type==TK_SEMI){cnt++;if(cnt==1&&out){out->loc.line=t->line;out->loc.col=t->col;out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2002;snprintf(out->msg,sizeof(out->msg),"free() called without NULL check");break;}}}}}return cnt;}
int check_use_after_free(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"free")==0&&f->tokens[i+1].type==TK_LPAREN){char*var=NULL;int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){var=f->tokens[j].text;for(int k=j+1;k<f->ntokens-1&&k<j+50;k++){if(f->tokens[k].type==TK_ID&&var&&strcmp(f->tokens[k].text,var)==0){TokenType next=f->tokens[k+1].type;if(next==TK_DOT||next==TK_ARROW||next==TK_LBRACK||next==TK_LPAREN){cnt++;if(cnt==1&&out){LOC_TOK(out,f,k);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2003;snprintf(out->msg,sizeof(out->msg),"Use after free of '%s'",var);snprintf(out->suggestion,sizeof(out->suggestion),"Set pointer to NULL after free");}}}}}}}return cnt;}
int check_double_free(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-5;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"free")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){char*var=f->tokens[j].text;for(int k=j+2;k<f->ntokens-2&&k<j+100;k++){if(f->tokens[k].type==TK_ID&&strcmp(f->tokens[k].text,"free")==0){int k2=k+2;if(k2<f->ntokens&&f->tokens[k2].type==TK_ID&&strcmp(f->tokens[k2].text,var)==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,k);out->sev=SEV_CRITICAL;out->cat=CAT_MEMORY;out->code=2004;snprintf(out->msg,sizeof(out->msg),"Double free of '%s'",var);snprintf(out->suggestion,sizeof(out->suggestion),"Ensure each allocation is freed exactly once");}}}}}}}return cnt;}
int check_memory_leak(SourceFile*f,Project*p,Issue*out){int cnt=0;int allocs=0;int frees=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID){if(strcmp(f->tokens[i].text,"malloc")==0||strcmp(f->tokens[i].text,"calloc")==0)allocs++;if(strcmp(f->tokens[i].text,"free")==0)frees++;}}if(allocs>frees+5){cnt=allocs-frees-5;if(out){out->loc.line=0;out->loc.col=0;out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2005;snprintf(out->msg,sizeof(out->msg),"Possible memory leaks: %d allocs vs %d frees",allocs,frees);snprintf(out->suggestion,sizeof(out->suggestion),"Ensure all allocated memory is freed");}}return cnt;}
int check_mismatched_alloc(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"malloc")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_LPAREN){int depth=1;int k=j+1;while(k<f->ntokens&&depth>0){if(f->tokens[k].type==TK_LPAREN)depth++;if(f->tokens[k].type==TK_RPAREN)depth--;if(depth==0){for(int m=k+1;m<f->ntokens-2;m++){if(f->tokens[m].type==TK_ID&&strcmp(f->tokens[m].text,"free")==0)break;if(f->tokens[m].type==TK_ID&&strcmp(f->tokens[m].text,"delete")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,m);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2006;snprintf(out->msg,sizeof(out->msg),"malloc/free vs new/delete mismatch");}}}}k++;}}}}return cnt;}
int check_uninit_var(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&i>0){int is_decl=0;for(int j=i-1;j>=0&&j>i-5;j--){if(f->tokens[j].type==TK_INT||f->tokens[j].type==TK_CHAR||f->tokens[j].type==TK_FLOAT||f->tokens[j].type==TK_DOUBLE||f->tokens[j].type==TK_VOID||f->tokens[j].type==TK_LONG||f->tokens[j].type==TK_SHORT||f->tokens[j].type==TK_STRUCT||f->tokens[j].type==TK_UNION){is_decl=1;break;}}if(is_decl){int has_init=0;for(int j=i+1;j<f->ntokens&&j<i+5;j++){if(f->tokens[j].type==TK_EQ){has_init=1;break;}if(f->tokens[j].type==TK_SEMI)break;}int used_uninit=0;if(!has_init){for(int j=i+5;j<f->ntokens&&j<i+50;j++){if(f->tokens[j].type==TK_ID&&strcmp(f->tokens[j].text,f->tokens[i].text)==0){if(j+1<f->ntokens&&(f->tokens[j+1].type==TK_PLUS||f->tokens[j+1].type==TK_MINUS||f->tokens[j+1].type==TK_STAR||f->tokens[j+1].type==TK_SLASH||f->tokens[j+1].type==TK_EQ||f->tokens[j+1].type==TK_DOT||f->tokens[j+1].type==TK_ARROW)){used_uninit=1;break;}}}}if(used_uninit){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2007;snprintf(out->msg,sizeof(out->msg),"Variable '%s' may be uninitialized",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Initialize variable at declaration");}}}}}return cnt;}
int check_stack_buffer_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_ID&&(strcmp(f->tokens[i].text,"strcpy")==0||strcmp(f->tokens[i].text,"strcat")==0||strcmp(f->tokens[i].text,"sprintf")==0||strcmp(f->tokens[i].text,"gets")==0||strcmp(f->tokens[i].text,"scanf")==0)){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2008;snprintf(out->msg,sizeof(out->msg),"Unsafe function '%s' may cause stack buffer overflow",f->tokens[i].text);snprintf(out->suggestion,sizeof(out->suggestion),"Use strncpy/strncat/snprintf with size limits");}}}return cnt;}
int check_heap_buffer_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-5;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"memcpy")==0){int j=i+3;if(j<f->ntokens&&f->tokens[j].type==TK_NUMBER){long long sz=f->tokens[j].val;for(int k=i-10;k<0;k++){if(k>=0&&f->tokens[k].type==TK_NUMBER&&f->tokens[k].val>0&&f->tokens[k].val<sz){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2009;snprintf(out->msg,sizeof(out->msg),"Potential heap buffer overflow in memcpy");snprintf(out->suggestion,sizeof(out->suggestion),"Verify destination buffer size");}}}}}}return cnt;}
int check_integer_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_NUMBER&&f->tokens[i+1].type==TK_STAR&&f->tokens[i+2].type==TK_NUMBER){long long a=f->tokens[i].val;long long b=f->tokens[i+2].val;if(a>0&&b>0&&a>LLONG_MAX/b){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2010;snprintf(out->msg,sizeof(out->msg),"Potential integer overflow in multiplication");snprintf(out->suggestion,sizeof(out->suggestion),"Use overflow-safe arithmetic or check bounds");}}}}return cnt;}
int check_alloca_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"alloca")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2011;snprintf(out->msg,sizeof(out->msg),"alloca() usage - stack allocation can cause overflow");snprintf(out->suggestion,sizeof(out->suggestion),"Use heap allocation (malloc) instead of alloca");}}}return cnt;}
int check_realloc_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"realloc")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2012;snprintf(out->msg,sizeof(out->msg),"realloc() without temporary variable can leak memory");snprintf(out->suggestion,sizeof(out->suggestion),"Use temporary pointer: tmp=realloc(p,s); if(tmp){p=tmp;}");}}}}return cnt;}
int check_flexible_array(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_RBRACK&&f->tokens[i+1].type==TK_SEMI&&f->tokens[i+2].type==TK_RBRACE){Token*t=&f->tokens[i];if(i>0&&f->tokens[i-1].type==TK_RBRACK){cnt++;if(cnt==1&&out){out->loc.line=t->line;out->loc.col=t->col;out->sev=SEV_INFO;out->cat=CAT_MEMORY;out->code=2013;snprintf(out->msg,sizeof(out->msg),"Flexible array member detected");snprintf(out->suggestion,sizeof(out->suggestion),"Ensure proper allocation for flexible array members");}}}}return cnt;}
int check_off_by_one(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-5;i++){if(f->tokens[i].type==TK_NUMBER&&f->tokens[i+1].type==TK_LBRACK&&f->tokens[i+2].type==TK_NUMBER&&f->tokens[i+3].type==TK_RBRACK){long long sz=f->tokens[i].val;long long idx=f->tokens[i+2].val;if(idx>=sz){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2014;snprintf(out->msg,sizeof(out->msg),"Off-by-one: index %lld out of bounds for array of size %lld",idx,sz);}}}}return cnt;}
int check_memset_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"memset")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){for(int k=i-1;k>=0&&k>i-20;k--){if(f->tokens[k].type==TK_ID){char buf_name[256];snprintf(buf_name,sizeof(buf_name),"%s",f->tokens[k].text);for(int m=i+3;m<f->ntokens&&m<i+10;m++){if(f->tokens[m].type==TK_NUMBER){long long sz=f->tokens[m].val;if(sz>8192){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2015;snprintf(out->msg,sizeof(out->msg),"memset with large size %lld may overflow buffer",sz);}}}}}}}}}return cnt;}
int check_memcpy_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"memcpy")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2016;snprintf(out->msg,sizeof(out->msg),"memcpy without size validation");snprintf(out->suggestion,sizeof(out->suggestion),"Validate destination size against source size");}}}return cnt;}
int check_strncpy_usage(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"strncpy")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2017;snprintf(out->msg,sizeof(out->msg),"strncpy does not guarantee null-termination");snprintf(out->suggestion,sizeof(out->suggestion),"Ensure destination buffer is null-terminated after strncpy");}}}return cnt;}
int check_sprintf_overflow(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"sprintf")==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2018;snprintf(out->msg,sizeof(out->msg),"sprintf can overflow buffer, use snprintf instead");snprintf(out->suggestion,sizeof(out->suggestion),"Replace sprintf with snprintf(buf, sizeof(buf), ...)");}}}return cnt;}
int check_variable_length_array(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LBRACK&&f->tokens[i+2].type==TK_ID){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_MEMORY;out->code=2019;snprintf(out->msg,sizeof(out->msg),"Variable-length array detected");snprintf(out->suggestion,sizeof(out->suggestion),"Use heap allocation instead of VLA for large sizes");}}}return cnt;}
