int check_dangling_pointer(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"free")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_ID){char*var=f->tokens[j].text;for(int k=j+2;k<f->ntokens-1&&k<j+80;k++){if(f->tokens[k].type==TK_STAR&&k+1<f->ntokens&&f->tokens[k+1].type==TK_ID&&strcmp(f->tokens[k+1].text,var)==0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,k);out->sev=SEV_ERROR;out->cat=CAT_MEMORY;out->code=2021;snprintf(out->msg,sizeof(out->msg),"Dangling pointer dereference after free");snprintf(out->suggestion,sizeof(out->suggestion),"Set pointer to NULL after freeing");}}}}}}return cnt;}
